## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/endovenousAblationLogic.ts`

```typescript
// Endovenous Ablation (Laser/Radiofrequency) Clinical Decision Logic
// Based on: SVS/AVF 2022 Clinical Practice Guidelines for Chronic Venous Disease
// Gloviczki P, et al. J Vasc Surg Venous Lymphat Disord. 2023;11(2):231-261.

export type CEAPClass = "C0" | "C1" | "C2" | "C3" | "C4" | "C5" | "C6";
export type AblationModality = "laser" | "rfa" | "mechanochemical" | "steam" | "";

export type EndovenousAblationInput = {
  age: string;
  ceapClass: string;
  gsv: boolean;                     // Great saphenous vein reflux
  ssv: boolean;                     // Small saphenous vein reflux
  refluxDuration: string;           // seconds on duplex
  veinDiameter: string;             // mm at SFJ/SPJ
  vcssScore: string;                // Venous Clinical Severity Score
  symptomDurationMonths: string;
  symptoms: string[];
  conservativeTherapyWeeks: string;
  compressionStockings: boolean;
  compressionWeeks: string;
  duplexConfirmed: boolean;
  standingReflux: boolean;
  priorDVT: boolean;
  activeUlcer: boolean;
  nonAmbulatory: boolean;
  pregnancy: boolean;
  activeInfection: boolean;
  coagulopathy: boolean;
  preferredModality: string;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return {
    I: "Class I — Recommended",
    IIa: "Class IIa — Reasonable",
    IIb: "Class IIb — May Be Considered",
    III: "Class III — Not Recommended / Contraindicated",
  }[cor];
}

export function getCORColor(cor: COR): string {
  return {
    I: "border-green-500 text-green-700",
    IIa: "border-blue-500 text-blue-700",
    IIb: "border-yellow-500 text-yellow-700",
    III: "border-red-500 text-red-700",
  }[cor];
}

export function assessEndovenousAblation(input: EndovenousAblationInput) {
  const contraindications: string[] = [];
  const rationale: string[] = [];
  const optimizationSteps: string[] = [];

  // Absolute contraindications
  if (input.pregnancy) contraindications.push("Pregnancy — defer elective ablation until postpartum");
  if (input.activeInfection) contraindications.push("Active skin/soft tissue infection overlying target vein — treat infection first");
  if (input.nonAmbulatory) contraindications.push("Non-ambulatory patient — endovenous ablation not indicated; consider compression only");
  if (input.coagulopathy) contraindications.push("Uncorrected coagulopathy — manage anticoagulation per procedural guidelines");

  if (contraindications.length > 0) {
    return {
      recommendation: "Endovenous Ablation Contraindicated",
      cor: "III" as COR,
      loe: "C",
      urgency: "Contraindicated",
      rationale: ["Absolute contraindication(s) identified — address before proceeding."],
      contraindications,
      optimizationSteps: [
        "Resolve contraindication(s) before reassessing candidacy",
        "Continue compression therapy in the interim",
      ],
      modalityNote: "",
    };
  }

  const ceapNum = parseInt(input.ceapClass.replace("C", "")) || 0;
  const refluxDuration = parseFloat(input.refluxDuration) || 0;
  const veinDiameter = parseFloat(input.veinDiameter) || 0;
  const compressionWeeks = parseFloat(input.compressionWeeks) || 0;
  const vcss = parseFloat(input.vcssScore) || 0;

  let cor: COR = "IIb";
  let urgency = "Elective";

  // SVS 2022 Grade 1A: CEAP C2-C6 with confirmed GSV/SSV reflux after compression trial
  if (
    ceapNum >= 2 &&
    (input.gsv || input.ssv) &&
    input.duplexConfirmed &&
    input.standingReflux &&
    refluxDuration >= 0.5 &&
    compressionWeeks >= 3
  ) {
    cor = "I";
    urgency = ceapNum >= 5 ? "Urgent (Active/Healed Ulcer)" : "Appropriate";
    rationale.push(`CEAP ${input.ceapClass} with duplex-confirmed ${input.gsv ? "GSV" : "SSV"} reflux ≥${refluxDuration}s in standing position`);
    rationale.push("Compression therapy trial completed (≥3 weeks)");
    rationale.push("SVS 2022 Grade 1A: Endovenous thermal ablation is recommended as first-line treatment for symptomatic truncal vein reflux");
    if (ceapNum >= 5) rationale.push("Active or healed venous ulcer (C5-C6) — ablation reduces ulcer recurrence by 50–70%");
  } else if (ceapNum >= 2 && (input.gsv || input.ssv) && input.duplexConfirmed && compressionWeeks >= 3) {
    cor = "IIa";
    urgency = "Reasonable";
    rationale.push(`CEAP ${input.ceapClass} with duplex-confirmed truncal reflux`);
    rationale.push("Compression trial completed — ablation is reasonable");
    if (refluxDuration < 0.5) optimizationSteps.push("Reflux duration <0.5s — confirm with standing duplex; borderline reflux may not meet payer criteria");
  } else if (ceapNum === 1 && (input.gsv || input.ssv) && input.duplexConfirmed) {
    cor = "IIb";
    urgency = "Symptomatic C1 — Consider Conservative Management";
    rationale.push("CEAP C1 (telangiectasias/reticular veins) — most payers require C2 or higher for thermal ablation");
    optimizationSteps.push("Document CEAP C2 or higher varicosities on duplex before requesting auth");
    optimizationSteps.push("Consider sclerotherapy for isolated C1 disease");
  } else if (compressionWeeks < 3) {
    cor = "IIb";
    urgency = "Continue Compression Therapy";
    rationale.push("Compression therapy trial insufficient — most payers require ≥3–6 weeks");
    optimizationSteps.push("Continue graduated compression stockings (20–30 mmHg) for ≥6 weeks");
    optimizationSteps.push("Document compliance and symptom response before requesting authorization");
  } else if (!input.duplexConfirmed) {
    cor = "IIb";
    urgency = "Duplex Ultrasound Required";
    rationale.push("Duplex ultrasound confirmation of reflux is required before ablation");
    optimizationSteps.push("Obtain bilateral lower extremity venous duplex with standing reflux protocol");
  } else {
    cor = "IIb";
    urgency = "Insufficient Criteria";
    optimizationSteps.push("Ensure CEAP C2 or higher is documented");
    optimizationSteps.push("Confirm duplex-documented reflux ≥0.5s in standing position");
    optimizationSteps.push("Complete ≥6-week compression stocking trial");
  }

  // Modality note
  let modalityNote = "";
  if (veinDiameter > 12) {
    modalityNote = "Vein diameter >12 mm: RFA may have higher occlusion rates; consider MOCA or laser with higher energy settings. Some operators prefer phlebectomy for very large veins.";
  } else if (veinDiameter < 3) {
    modalityNote = "Vein diameter <3 mm: Endovenous thermal ablation may be technically challenging; consider sclerotherapy as alternative.";
  } else {
    modalityNote = "Vein diameter within standard range (3–12 mm): Both EVLA and RFA are appropriate with comparable 5-year occlusion rates (~95%).";
  }

  if (input.priorDVT) {
    rationale.push("Prior DVT: Confirm absence of post-thrombotic obstruction on duplex before ablation; obtain hematology consultation if thrombophilia suspected");
  }

  if (vcss >= 8) {
    rationale.push(`VCSS ${vcss} (moderate-severe) — supports medical necessity for ablation`);
  }

  return {
    recommendation:
      cor === "I"
        ? "Endovenous Ablation Recommended"
        : cor === "IIa"
        ? "Endovenous Ablation Reasonable"
        : urgency === "Continue Compression Therapy"
        ? "Continue Compression Therapy — Ablation Premature"
        : urgency === "Duplex Ultrasound Required"
        ? "Duplex Ultrasound Required Before Ablation"
        : "Insufficient Criteria for Ablation",
    cor,
    loe: ceapNum >= 4 ? "A" : ceapNum >= 2 ? "B" : "C",
    urgency,
    rationale,
    contraindications,
    optimizationSteps,
    modalityNote,
  };
}
